INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1320486-ise405', 'stk-user2352', 'ISE 405', 'info', '{"desc": "المحاكاة Simulation باستخدام الحاسب هي أحد الوسائل الحديثة المستخدمة لدراسة العمليات الصناعية والخدمية. المحاكاة -وهي أحد وسائل الهندسة الصناعية- تستخدم لدراسة مشاريع التطوير والاستثمار. تأمَّل المثال التالي:\n\nأنت مدير مسئولٌ عن مصنعٍ به ماكينة واحدة. هذه الماكينة تستغرق 10 دقائق لتصنيع قطعة واحدة. ما الذي يحدث إذا استخدمنا ماكينة تحتاج خمس دقائق فقط لإنتاج قطعة واحدة؟\n\nمن اليسير أن نجيب بأن الإنتاج سيزيد إلى الضعف.\n\nماذا لو كانت هذه الماكينة تنتج منتج نصف مصنع ويتم استكمال التصنيع في ماكينة أخرى؟ في هذه الحالة يتوقف الإنتاج على الماكينة التي تستغرق وقتا أطول.\n\nنحن هنا نفترض افتراضاُ لا يتحقق في أغلب الحالات. نحن نفترض أن وقت التشغيل هو وقت ثابت. في الواقع يختلف وقت التشغيل من قطعة لأخرى وكذلك تحدث أعطال في الماكينة بشكل عشوائي وبعض المنتجات تكون معيبة وقد تحتاج إعادة تشغيل. بالإضافة لذلك فإن كثير من العمليات تتكون من عدد من العمليات التشغيلية –والتي قد تختلف من منتج لآخر- وعمليات نقل مواد خام ونصف مصنعة عن طريق معدات نقل مختلفة. عندما ننظر إلى العملية الإنتاجية بهذا الشكل الواقعي نجد أن هناك كثير من الحالات التي لا يمكن دراستها بحلول رياضية وهنا تظهر قيمة استخدام المحاكاة\n\nباستخدام الحاسب يمكننا أن نحاكي العملية الصناعية أو الخدمية. هذه المحاكاة تمكننا من دراسة نتائج تشغيل العملية لمدة أيام في دقائق معدودة وتمكننا من تحديد المناطق الحرجة في العملية وتأثير إحداث تغييرات في أسلوب العمل أو زيادة معدات أو أفراد.\n\nالمحاكاة ليست أسلوبا جديدا، فكثيرا ما نستخدم المحاكاة الحقيقية لاتخاذ قرار ما. فقد نقوم باستخدام أسلوب عمل جديد لمدة ثلاثة أيام على سبيل التجربة، ثم نقوم بتحليل نتائج مؤشرات الأداء خلال هذه الأيام لكي نقرر إن كان هذا الأسلوب مفيدا أم لا. ولكن هذا الأسلوب قد يتسبب في تكاليف عالية لأن تجربة أساليب العمل في الواقع قد تؤدي إلى خسائر عديدة. بالإضافة لذلك فبعض الأمور لا يمكن تجربتها إلا بعد الاستثمار في شراء معدات أو إنشاء مبنى. المحاكاة باستخدام الحاسب تمكننا من دراسة هذه المشاريع بدون المخاطرة بحدوث خسائر في الإنتاج أو مشاكل في مستوى الخدمة أو خسائر من شراء معدات لا تؤدي إلى النتائج المتوقعة.\n\nلكي نقوم بمحاكاة عملية ما فإننا لابد أن نتفهم العملية جيدا وأن نقوم بتحديد البيانات التي نحتاجها ونقوم بتجميعها. لكي نحاكي العملية الإنتاجية فإننا نحتاج أن نجعل الحاسب يعرف خطوات العملية والأجزاء المكونة لها من معدات وخامات وأناس وأماكن. يوجد العديد من برامج المحاكاة التي تمكننا من إدخال هذه المعلومات بأسلوب غير معقد مثل برامج: ARENA أو ProModel\n\nيتم إدخال البيانات بأسلوب يسمح للبرنامج بمحاكاة التغيرات المنتظمة والعشوائية التي تحدث في الواقع. لذلك فإننا عادة لا نستخدم المتوسط الحسابي للتعبير عن زمن عملية ما ولكننا نستخدم العديد من القياسات المختلفة لهذه العملية وهكذا بالنسبة للأزمنة الأخرى التي نستخدمها في محاكاة هذه العملية مثل أوقات التحميل وأوقات فحص المنتج و معدل حضور العملاء. إمكانية محاكاة التغيرات في أزمنة التشغيل والنقل وخلافه هي أحد المزايا الرئيسية لاستخدام المحاكاة.\n\nقبل أن نبدأ في استخدام نموذج المحاكاة لدراسة العملية الإنتاجية أو الخدمية فلابد أن نتأكد أن النموذج يعطي نتائج جيدة. لذلك فإننا نبدأ بتشغيل النموذج على الحالة الموجودة حاليا ثم نقارن بعض النتائج بالنتائج الواقعية وفي حالة التطابق فإننا نطمئن إلى صحة النموذج. فمثلا قد نقارن حجم الإنتاج اليومي أو معدل الانتظار أو معدل المخزون وهكذا.\n\nبعد التأكد من صحة النموذج يمكننا استخدامه لدراسة حالات عديدة ومقارنة نتائجها. فالمحاكاة تمكننا من الإجابة عن العديد من الأسئلة من نوع “ماذا لو ……” مثل: ماذا لو توقفت هذه الماكينة، ماذا لو أضفنا عامل فني ، ماذا لو عملنا بنصف العمالة، ماذا لو أضفنا سيارة أخرى، ماذا لو تم تقليل وقت التشغيل ون كذا ثانية إلى كذا ثانية…….كثير من برامج المحاكاة تمكننا كذلك من مشاهدة رسوم متحركة تعبر عن حركة المواد والأفراد والمعدات وهذه الرسومات تساعدنا في تتبع العملية وتحديد بعض نقاط الضعف. ولكن القيمة الأكبر للمحاكاة تكمن في البيانات الإحصائية التي نحصل عليها والتي تساعدنا على المقارنة بين أنظمة عمل مختلفة أو اقتراحات توسع مختلفة.\n\nصعوبة استخدام المحاكاة تتمثل في الحاجة لشخص على دراية بأسلوب استخدامه، الحاجة لشراء برنامج، المجهود اللازم لتجميع البيانات اللازمة. على الجانب الآخر، فإن المحاكاة تساعدنا على دراسة مشاكل معقدة ومشاريع مكلفة مما يترتب عليه التأكد من جدوى الاستثمار أو الوصول إلى طريقة أفضل أو الوصول إلى عدم جدواه. من مميزات المحاكاة، أنه بمجرد بناء نموذج صحيح فإنه يمكننا استخدامه لدراسة حالات كثيرة في وقت قصير. فمثلا قد نحتاج شهر أو شهرين لبناء نموذج لعملية معقدة، ثم نحتاج إلى بضع ساعات لدراسة العديد من الحالات ومقارنتها. فيمكننا دراسة نتائج التشغيل خلال شهر في ربع أو نصف ساعة.\n\nمن الأمثلة التي تستخدم فيها المحاكاة\n\nدراسة أفضل الطرق لتقليل وقت انتظار العملاء في السوبر ماركت (السوق التجاري)\nدراسة الحاجة لشراء معدة جديدة أو تعيين عاملين جدد ومعرفة تأثير ذلك على مؤشرات الأداء\nدراسة التخطيط المناسب لمستشفى أو مصنع أو مطعم\nدراسة أسلوب تطوير عملية إدارية مثل عملية شراء خامات وقطع غيار في شركة ما\nمجالات تطبيق المحاكاة تشمل\n\nالمصانع لدراسة العمليات الإنتاجية\nالمستشفيات لدراسة تنظيم أوقات عمل الأطباء والممرضين وللوصول إلى جدولة جيدة لغرف العمليات وغرفة الطوارئ\nالمحلات الكبرى لدراسة كيفية تيسير حركة مرور العملاء وتقليل أوقات الانتظار وتحديد الحاجة لموظفين خدمة عملاء\nالملاعب الرياضية الكبيرة والمطارات والمستشفيات لدراسة حركة الأفراد والمرضى والطائرات وأوقات الانتظار\nالطرق لدراسة سهولة مرور السيارات\nأماكن التجمع الكبرى مثل المناسبات العالمية والحج لتيسير حركة مرور الحجاج وتقليل الازدحام والحوادث ودراسة الاقتراحات المختلفة لتغيير بعض المسارات مثل ما يحدث في رمي الجمرات\nعمليات النقل البري والبحري لدراسة الاحتياج لزيادة معدات نقل والعائد من شرائها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-405-stochastic-systems-simulation/120946/8", "user": "user2352", "ts": 1390018057000, "tid": 120946, "pn": 8}}', 1390018057000, 1794828445, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1450452-ise405', 'stk-fahad_2012', 'ISE 405', 'info', '{"desc": "الـ 405 واحد من اهم كورسات التخصص\nالكورس يتكلم عن المحاكاة , كيف ممكن تحاكي اي نظام عندك مثل خدمة العملاء في البنك او في المطعم , محاكاة لسير المنتجات في المصنع …\nانصح باخذ الكورس مع الدكتور الحبوبي بحكم انه مختص وفاهم لهذا الكورس بشكل كبير\nوله تطبيقات كثيرة في الكورس في الحج والعمرة والجمرات\n\nجودة المقرر بشكل عام : ممتازة\n\nالمواضيع التي يغطيها المقرر : Simulation , Queuing , Random Number generation , Manual Simulation\n\nالكتاب المستخدم للمقرر : اعتمدت عالسلايدات بشكل كامل وماعندي فكرة عن الكتاب للامانة\n\nمدى فائدته في الناحية التطبيقية :\nراح تطبق الكورس في اللاب بشكل كامل\nاللاب بيحتاج شغل واهتمام ومتابعة في اللاب عشان تفهمه\nبيكون عندك اسايمنت للاب بشكل اسبوعي عبارة عن تطبيق لدرس اللاب\n\nالكورس بشكل عام متوسط الصعوبة ويفضل اخذه مع دكتور شريح\n\nسيلبس المادة في المرفقات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-405-stochastic-systems-simulation/120946/20", "user": "Fahad_2012", "ts": 1464245797000, "tid": 120946, "pn": 20}}', 1464245797000, 1794828445, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1533448-ise405', 'stk-faisalovic', 'ISE 405', 'info', '{"desc": "TERM -211\nالشباب فوق ما قصروا اعطوا تعريف كافي عن الكورس، وللإختصار باتطرق للجوانب اللي ممكن تحتاجها/ينها\nالكورس له ليكتشر ولاب. الكونسبت حق الليكتشر ما تحتاجه فاللاب لكن الميد والفاينل كلها من كونسبت الليكتشر. اللاب بالنسبه لي كان سهل\nبس تحتاج تركز مع الدكتور وتحل الاسايمنت حق اللاب بعد نهاية اللاب مباشره. + فيه ميد وفاينل للاب، غالباً تكون مشابهه لأفكار الاسايمنتز حقت اللاب. الكونسبت حق الليكتشر له علاقه ب 205 +215. الماده بشكل عام مش صعبه ومش ثقيله لكن تحتاج تمسكها اول بأول + راح يكون عندك التاسكات حقت اللاب تحتاج ترفعها كل اسبوع فنصيحه حلها مباشره بعد اللاب عشان ما تتراكم عليك التاسكات. فيه بروجيكت على برنامج ARENA SIMULATION (هذا هو البرنامج اللي راح تشتغلون عليه كل فاللاب).\n\nالرابط هذا فيه شرح كامل للكورس للدكتورالصوافي، الشرح وافي وكافي بس خل السرعة 2x.\nISE 405 - Lec - Google Drive\n\nبالتوفيق وفالكم ال A+، ولاتنسوني من دعائكم.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-405-stochastic-systems-simulation/120946/24", "user": "FAISALOVIC", "ts": 1642104404000, "tid": 120946, "pn": 24}}', 1642104404000, 1794828445, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1504948-ise405', 'stk-mkd', 'ISE 405', 'info', '{"desc": "يمسيكم بالخير، الدكتور يوسف أبو عسكر ما هو موجود بقسم أعضاء هيئة التدريس ، اذا فيه احد ممكن يضيفه للقسم ويعطيكم العافيه ( تقييمي للدكتور بأكتبه تحت ) :\n\nالسمستر والمادة: ISE 405 Lab – Term 172\n\nما ودي أكثر كلام ، أستاذ يوسف أبو عسكر من أفضل من درسني بالجامعة كلها ، حرفيا من أفضل لابات الجامعة اللي خذتها. الله يذكره بالخير\n\nإضافات: بقول كم شي السريع بس عشان تكون بالصورة : حاول تركز مع الدكتور باللاب قد ما تقدر بتساعدك بعدين بالمذاكرة ، لا تضيع دقيقة وحدة وانت منت مركز معه بتفيدك بعدين لانه يركز على تفاصيل صغيرة مهمة وافهم يا فهيم. بالنسبة للهومووركات خله ينزلكم السلوشن مع الديو عشان تعرف اغلاطك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yousef-abouaskar/180880/1", "user": "MKD", "ts": 1547533774000, "tid": 180880, "pn": 1}}', 1547533774000, 1794828445, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2352-ise405', 'stk-user2352', 'ISE 405', 'doc', '{"docs": [{"id": "stk-dr-f118599", "n": "Dr. Yahya Cinar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "باختصار :\nهو يحضر حالياً درجة الدكتوراه في الجامعة ، وهو من تركيا ، واخلاقه عالية ، وتوه شباب عمره 27 سنة ،،\n\nأنصح به لمادة ise405 بصفته يشرح باختصار ولا يحب التعقيد واختباراته معقولة على كلام الشباب اللي درسا معاه لاب405 الترم الماضي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1076104-ise405", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-yahya-cinar/118599/4", "user": "user2352", "ts": 1344187934000, "tid": 118599, "pn": 4}}, {"id": "stk-dr-f98655", "n": "Dr. M Dhurgham", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE-405 نقلا عن أحد الخريجين\n\nالتحضير : يحضر إذا شاف الغياب كثير عن طريق QUIZ سهل\n\nالشرح : متوسط وفي البداية يطلب من الطلاب مراجعة شابتر 3+4 من كتاب ISE205\nالكويزات : سهلة وأغلبها من HW ومسائل الكتاب\nالمياجر: فيه ميدتيرم متوسط لسهل مع سؤال واحد فيه فكرة\nالفاينلات : متوسط وفيه يمكن سؤالين تحتاج لفهم يحلها المتمرس على حل جميع مسائل الكتاب بنهاية كل شابتر\nالقريد النهائي: يعطيك حقك وإذا أنت مبدع في البروجكت واللاب وتشارك معه احتمال يعطي Upgrade\nالصوت: واضح\nإضافات : الدكتور شاب ويقدّر المجتهدين معه اللي يشاركون ويحضرون ولا يغيبون\nوالدكتور كمان فاهم في برنامج ARENA المستخدم في لاب الكورس 30%\nالدكتور باختصار يصلح للدوافير الجادين فقط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1419382-ise405", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-dhurgham/98655/28", "user": "user2352", "ts": 1418192138000, "tid": 98655, "pn": 28}}]}', 1344187934000, 1794828445, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mkd-ise405', 'stk-mkd', 'ISE 405', 'doc', '{"docs": [{"id": "stk-dr-f172118", "n": "Dr. Hany Osman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السمستر والمادة: ISE 405 – Term 172\n\nالتعامل: عادي، يشدد على خروج الطلاب من الكلاس اذا شاف اكثر من واحد يطلعون\n\nالصوت: واضح لكن اكسنت مصري يغطي الكلام كله، اذا انت متعود عوافي\n\nالشرح: يفهمك زين اذا انت مركز معه، ما كان شرحه بطال لكن يمديك تمشي امورك فيه اذا تبي الموضوع يصير سهالات\n\nالتحضير: يحضر بالاسماء بالبداية، واذا شاف ناس ناقصين يحضر مرتين بأول الكلاس وآخره ( بعد نص الترم صار متساهل شوي يحضر بالاخير )\n\nالتصحيح: عادي ، اذا حليت أسئلة كونسبت بالاختبارات من فهمك عادي عنده اهم شي انك توصل الفكره ، بشكل عام مب بطال\n\nالمياجر والفاينل (الاختبارات بشكل عام):الميد جانا طويل واسئلته غريبة جدا، السؤال حرفيا صفحة كاملة A4 والاجابة سطرين وجدول بسيط ! طبعا ما كان حاط لنا الجدول لازم تعرف بنفسك طريقة الجواب الصحيحة وانك لازم تحطها بجدول ( اللي يأخذ المادة بيفهم كلامي ) وجاب برضو بالميد أسئلة كونسبت وتصحيحها كان جدا جيد. الفاينل جانا كويس الحمد الله من اللي شرحه الدكتور، ركز عالبراكتس اللي بيعطيكم إياها .\n\nإضافات: أي شي زيادة بحطها بموضوع المادة نفسها ISE 405", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504895-ise405", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hany-osman/172118/6", "user": "MKD", "ts": 1547468830000, "tid": 172118, "pn": 6}}]}', 1547468830000, 1794828445, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
